(()=>{'use strict';const $=id=>document.getElementById(id);const btn=$('retry');async function load(){btn.disabled=true;$('status').textContent='Retrieving source headlines…';$('summary').textContent='Loading today’s briefing…';$('headlines').replaceChildren();try{const res=await fetch('/api/news/daily',{headers:{'Accept':'application/json'}});if(!res.ok)throw Error('HTTP '+res.status);const data=await res.json();$('date').textContent=data.date_utc+' UTC';const diag=$('feedDiagnostics');const statuses=Array.isArray(data.feed_status)?data.feed_status:[];diag.hidden=!statuses.length;diag.replaceChildren();if(statuses.length){const details=document.createElement('details'),sum=document.createElement('summary'),ul=document.createElement('ul');sum.textContent='SOURCE STATUS · '+statuses.filter(s=>s.status==='ok').length+' / '+statuses.length+' reporting';details.append(sum);for(const st of statuses){const li=document.createElement('li');li.textContent=st.source+': '+(st.status==='ok'?st.count+' recent item(s)':st.status==='no_recent_items'?'reachable, no recent items':'unavailable'+(st.reason?' ('+st.reason+')':''));ul.append(li)}details.append(ul);diag.append(details)}$('summary').textContent=data.summary||('AI summary unavailable: '+(data.summary_note||'Please retry later.'));$('status').textContent=data.headlines.length?('LATEST BRIEFING · '+data.headlines.length+' SOURCED HEADLINES'):(data.source_status==='sources_unreachable'?'External news feeds are unreachable from the server. Source details are available below; retry shortly.':'No recent dated coverage is available from the responding feeds.');$('count').textContent=data.headlines.length+' HEADLINES · RECENT COVERAGE';for(const [i,item] of data.headlines.entries()){const li=document.createElement('li'),wrap=document.createElement('div'),link=document.createElement('a'),meta=document.createElement('div');link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=item.title;meta.className='meta';meta.textContent=item.channel+' · '+new Date(item.published_utc).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short',timeZone:'UTC'})+' UTC · SOURCE '+(i+1);wrap.append(link,meta);li.append(wrap);$('headlines').append(li);}if(!data.headlines.length){const li=document.createElement('li');li.textContent='No recent dated headlines were found. This does not indicate whether tropical cyclones are active.';$('headlines').append(li);}}catch(e){$('status').textContent='Unable to load the briefing right now.';$('summary').textContent='The news feed is unavailable. Check your connection and try again.';}finally{btn.disabled=false}}btn.addEventListener('click',load);load()})();